14		"github.com/entireio/cli/cmd/entire/cli/settings"
15	
16		"github.com/go-git/go-git/v6"
17		"github.com/go-git/go-git/v6/plumbing"
18		"github.com/go-git/go-git/v6/plumbing/object"
19	)
20	
21	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
22	// The target can be a remote name (e.g., "origin") or a URL for direct push.
23	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
24	// no remote tracking refs — git itself handles the no-op case.
25	// Does not check any settings — callers are responsible for gating.
26	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
27		repo, err := OpenRepository(ctx)
28		if err != nil {
29			return nil //nolint:nilerr // Hook must be silent on failure
30		}
31	
32		// Check if branch exists locally
33		branchRef := plumbing.NewBranchReferenceName(branchName)
34		localRef, err := repo.Reference(branchRef, true)
35		if err != nil {
36			// No branch, nothing to push
37			return nil //nolint:nilerr // Expected when no sessions exist yet
38		}
39	
40		// Only check remote tracking refs when target is a remote name (not a URL).
41		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
42		if !isURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
43			return nil
44		}
45	
46		return doPushBranch(ctx, target, branchName)
47	}
48	
49	// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
50	// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
51	func hasUnpushedSessionsCommon(repo *git.Repository, remote string, localHash plumbing.Hash, branchName string) bool {
52		// Check for remote tracking ref: refs/remotes/<remote>/<branch>
53		remoteRefName := plumbing.NewRemoteReferenceName(remote, branchName)
54		remoteRef, err := repo.Reference(remoteRefName, true)
55		if err != nil {
56			// Remote branch doesn't exist yet - we have content to push
57			return true
58		}
59	
60		// If local and remote point to same commit, nothing to sync
61		// This is the only case where we skip - any difference needs handling
62		return localHash != remoteRef.Hash()
63	}
64	
65	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
66	// The target can be a remote name or a URL.
67	func doPushBranch(ctx context.Context, target, branchName string) error {
68		displayTarget := target
69		if isURL(target) {
70			displayTarget = "checkpoint remote"
71		}
72	
73		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
74		stop := startProgressDots(os.Stderr)
75	
76		// Try pushing first
77		if result, err := tryPushSessionsCommon(ctx, target, branchName); err == nil {
78			finishPush(ctx, stop, result, target)
79			return nil
80		}
81		stop("")
82	
83		// Push failed - likely non-fast-forward. Try to fetch and rebase.
84		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
85		stop = startProgressDots(os.Stderr)
86	
87		if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
88			stop("")
89			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
90			printCheckpointRemoteHint(target)
91			return nil // Don't fail the main push
92		}
93		stop(" done")
94	
95		// Try pushing again after rebase
96		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
97		stop = startProgressDots(os.Stderr)
98	
99		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
100			stop("")
101			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
102			printCheckpointRemoteHint(target)
103		} else {
104			finishPush(ctx, stop, result, target)
105		}
106	
107		return nil
108	}
109	
110	// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
111	// Only prints when the target is a URL (not the user's default remote).
112	func printCheckpointRemoteHint(target string) {
113		if !isURL(target) {
114			return
115		}
116		fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
117		fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
118	}
119	
120	// settingsHintOnce ensures the settings commit hint prints at most once per process.
121	var settingsHintOnce sync.Once
122	
123	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
124	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
125	// entire.io discovers the external checkpoint repo by reading the committed project
126	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
127	// (not just in settings.local.json or uncommitted local changes).
128	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
129	// single pre-push invocation.
130	func printSettingsCommitHint(ctx context.Context, target string) {
131		if !isURL(target) {
132			return
133		}
134		settingsHintOnce.Do(func() {
135			if isCheckpointRemoteCommitted(ctx) {
136				return
137			}
138			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
139		})
140	}
141	
142	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
143	// at HEAD contains a valid checkpoint_remote configuration. This is the true
144	// discoverability check: entire.io reads from committed project settings, not from
145	// local overrides or uncommitted changes.
146	func isCheckpointRemoteCommitted(ctx context.Context) bool {
147		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
148		output, err := cmd.Output()
149		if err != nil {
150			return false // file doesn't exist at HEAD
151		}
152		// Parse the committed content and check for checkpoint_remote
153		committed, err := settings.LoadFromBytes(output)
154		if err != nil {
155			return false
156		}
157		return committed.GetCheckpointRemote() != nil
158	}
159	
160	// pushResult describes what happened during a push attempt.
161	type pushResult struct {
162		// upToDate is true when the remote already had all commits (nothing transferred).
163		upToDate bool
164	}
165	
166	// parsePushResult checks git push output for known status strings and returns
167	// a pushResult. git prints "Everything up-to-date" to stderr when nothing was pushed.
168	func parsePushResult(output string) pushResult {
169		return pushResult{
170			upToDate: strings.Contains(output, "Everything up-to-date") ||
171				strings.Contains(output, "everything up-to-date"),
172		}
173	}
174	
175	// finishPush stops the progress dots and prints "already up-to-date" or "done"
176	// depending on the push result. Only prints the settings commit hint when new
177	// content was actually pushed.
178	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
179		if result.upToDate {
180			stop(" already up-to-date")
181		} else {
182			stop(" done")
183			printSettingsCommitHint(ctx, target)
184		}
185	}
186	
187	// tryPushSessionsCommon attempts to push the sessions branch.
188	func tryPushSessionsCommon(ctx context.Context, remote, branchName string) (pushResult, error) {
189		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
190		defer cancel()
191	
192		// Use --no-verify to prevent recursive hook calls
193		cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", remote, branchName)
194	
195		output, err := cmd.CombinedOutput()
196		outputStr := string(output)
197		if err != nil {
198			// Check if it's a non-fast-forward error (we can try to recover)
199			if strings.Contains(outputStr, "non-fast-forward") ||
200				strings.Contains(outputStr, "rejected") {
201				return pushResult{}, errors.New("non-fast-forward")
202			}
203			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
204		}
205	
206		return parsePushResult(outputStr), nil
207	}
208	
209	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
210	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
211	// always apply cleanly.
212	// The target can be a remote name or a URL.
213	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
214		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
215		defer cancel()
216	
217		// Determine fetch refspec. When target is a URL, use a temp ref;
218		// when it's a remote name, use the standard remote-tracking ref.
219		var fetchedRefName plumbing.ReferenceName
220		var refSpec string
221		if isURL(target) {
222			tmpRef := "refs/entire-fetch-tmp/" + branchName
223			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
224			fetchedRefName = plumbing.ReferenceName(tmpRef)
225		} else {
226			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
227			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
228		}
229	
230		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
231		// Use --filter=blob:none for a partial fetch that downloads only commits
232		// and trees, skipping blobs. The merge only needs the tree structure to
233		// combine entries; blobs are already local or fetched on demand.
234		fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, refSpec)
235		if output, err := fetchCmd.CombinedOutput(); err != nil {
236			return fmt.Errorf("fetch failed: %s", output)
237		}
238	
239		repo, err := OpenRepository(ctx)
240		if err != nil {
241			return fmt.Errorf("failed to open git repository: %w", err)
242		}
243	
244		// Reconcile disconnected metadata branches before rebasing.
245		// The fetch above updated the remote-tracking ref, so reconciliation
246		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
247		// this cherry-picks local commits onto remote tip, updating the local ref.
248		// If reconciliation fails, abort — proceeding to rebase on disconnected
249		// branches would silently combine unrelated histories.
250		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
251			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
252		}
253	
254		// Get local branch (re-read after potential reconciliation update)
255		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
256		if err != nil {
257			return fmt.Errorf("failed to get local ref: %w", err)
258		}
259	
260		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
261		remoteRef, err := repo.Reference(fetchedRefName, true)
262		if err != nil {
263			return fmt.Errorf("failed to get remote ref: %w", err)
264		}
265	
266		// If local is already at or behind remote, fast-forward
267		if localRef.Hash() == remoteRef.Hash() {
268			return nil
269		}
270	
271		// Find merge base
272		repoPath, err := getRepoPath(repo)
273		if err != nil {
274			return fmt.Errorf("failed to get repo path: %w", err)
275		}
276		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
277		if err != nil {
278			return fmt.Errorf("failed to find merge base: %w", err)
279		}
280	
281		// If local is ancestor of remote (merge base == local), fast-forward to remote
282		if mergeBase == localRef.Hash() {
283			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
284			if err := repo.Storer.SetReference(ref); err != nil {
285				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
286			}
287			if isURL(target) {
288				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
289			}
290			return nil
291		}
292	
293		// Collect commits reachable from local but not from remote and cherry-pick
294		// them onto the remote tip. This preserves local-only commits even when the
295		// local metadata branch already contains old merge commits, while avoiding
296		// replaying shared ancestors older than the true merge-base.
297		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
298		if err != nil {
299			return fmt.Errorf("failed to collect local commits: %w", err)
300		}
301	
302		if len(localCommits) == 0 {
303			// No local-only commits — just point to remote
304			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
305			if err := repo.Storer.SetReference(ref); err != nil {
306				return fmt.Errorf("failed to update branch ref: %w", err)
307			}
308			if isURL(target) {
309				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
310			}
311			return nil
312		}
313	
314		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
315		if err != nil {
316			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
317		}
318	
319		// Update branch ref
320		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
321		if err := repo.Storer.SetReference(newRef); err != nil {
322			return fmt.Errorf("failed to update branch ref: %w", err)
323		}
324	
325		// Clean up temp ref if we used one (best-effort, not critical if it fails)
326		if isURL(target) {
327			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
328		}
329	
330		return nil
331	}
332	
333	// getMergeBase returns the merge base hash of two commits, or an error if they
334	// have no common ancestor.
335	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
336		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
337		defer cancel()
338	
339		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
340		cmd.Dir = repoPath
341		output, err := cmd.Output()
342		if err != nil {
343			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
344		}
345	
346		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
347	}
348	
349	// collectCommitsSince returns non-merge commits reachable from tip but not from
350	// exclude, ordered oldest-first in topological order.
351	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
352		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
353		defer cancel()
354	
355		// cherryPickOnto computes each commit's delta against its first parent, so
356		// replaying merge commits would incorrectly re-apply changes that arrived via
357		// non-first-parent history. Limit the replay set to non-merge commits.
358		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
359		cmd.Dir = repoPath
360		output, err := cmd.Output()
361		if err != nil {
362			return nil, fmt.Errorf("git rev-list failed: %w", err)
363		}
364	
365		lines := strings.Fields(string(output))
366		if len(lines) > MaxCommitTraversalDepth {
367			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
368		}
369	
370		commits := make([]*object.Commit, 0, len(lines))
371		for _, line := range lines {
372			hash := plumbing.NewHash(line)
373			commit, commitErr := repo.CommitObject(hash)
374			if commitErr != nil {
375				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
376			}
377			if len(commit.ParentHashes) > 1 {
378				continue
379			}
380			commits = append(commits, commit)
381		}
382	
383		return commits, nil
384	}
385	
386	// startProgressDots prints dots to w every second until the returned stop function
387	// is called. The stop function prints the given suffix and a newline.
388	func startProgressDots(w io.Writer) func(suffix string) {
389		done := make(chan struct{})
390		stopped := make(chan struct{})
391		go func() {
392			defer close(stopped)
393			ticker := time.NewTicker(time.Second)
394			defer ticker.Stop()
395			for {
396				select {
397				case <-done:
398					return
399				case <-ticker.C:
400					fmt.Fprint(w, ".")
401				}
402			}
403		}()
404		return func(suffix string) {
405			close(done)
406			<-stopped // Wait for goroutine to finish before writing suffix
407			fmt.Fprintln(w, suffix)
408		}
409	}
410	
411	// isURL returns true if the target looks like a URL rather than a git remote name.
412	func isURL(target string) bool {
413		return strings.Contains(target, "://") || strings.Contains(target, "@")
414	}
415	
416	// createMergeCommitCommon creates a merge commit with multiple parents.
417	func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
418		authorName, authorEmail := GetGitAuthorFromRepo(repo)
419		now := time.Now()
420		sig := object.Signature{
421			Name:  authorName,
422			Email: authorEmail,
423			When:  now,
424		}
425	
426		commit := &object.Commit{
427			TreeHash:     treeHash,
428			ParentHashes: parents,
429			Author:       sig,
430			Committer:    sig,
431			Message:      message,
432		}
433	
434		obj := repo.Storer.NewEncodedObject()
435		if err := commit.Encode(obj); err != nil {
436			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
437		}
438	
439		hash, err := repo.Storer.SetEncodedObject(obj)
440		if err != nil {
441			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
442		}
443	
444		return hash, nil
445	}
