43	// tryPushRef attempts to push a custom ref using an explicit refspec.
44	func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) (pushResult, error) {
45		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
46		defer cancel()
47	
48		// Use --no-verify to prevent recursive hook calls (this runs inside pre-push)
49		refSpec := fmt.Sprintf("%s:%s", refName, refName)
50		cmd := CheckpointGitCommand(ctx, target, "push", "--no-verify", target, refSpec)
51	
52		output, err := cmd.CombinedOutput()
53		outputStr := string(output)
54		if err != nil {
55			if strings.Contains(outputStr, "non-fast-forward") ||
56				strings.Contains(outputStr, "rejected") {
57				return pushResult{}, errors.New("non-fast-forward")
58			}
59			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
60		}
61	
62		return parsePushResult(outputStr), nil
63	}
