65	// doPushRef pushes a custom ref with fetch+merge recovery on conflict.
66	func doPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
67		displayTarget := target
68		if isURL(target) {
69			displayTarget = "checkpoint remote"
70		}
71	
72		shortRef := shortRefName(refName)
73		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
74		stop := startProgressDots(os.Stderr)
75	
76		if result, err := tryPushRef(ctx, target, refName); err == nil {
77			finishPush(ctx, stop, result, target)
78			return nil
79		}
80		stop("")
81	
82		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", shortRef)
83		stop = startProgressDots(os.Stderr)
84	
85		if err := fetchAndMergeRef(ctx, target, refName); err != nil {
86			stop("")
87			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", shortRef, err)
88			printCheckpointRemoteHint(target)
89			return nil
90		}
91		stop(" done")
92	
93		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
94		stop = startProgressDots(os.Stderr)
95	
96		if result, err := tryPushRef(ctx, target, refName); err != nil {
97			stop("")
98			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", shortRef, err)
99			printCheckpointRemoteHint(target)
100		} else {
101			finishPush(ctx, stop, result, target)
102		}
103	
104		return nil
105	}
